CREATE VIEW render_ready_manifests AS SELECT m.id,m.project_id,m.content_hash FROM current_render_manifests m JOIN projects p ON p.id=m.project_id WHERE p.active_manifest_id=m.id AND m.status='APPROVED' AND EXISTS(SELECT 1 FROM qa_reports q WHERE q.manifest_id=m.id AND q.kind='PRE_RENDER' AND q.status='APPROVED' AND q.version_no=(SELECT max(latest.version_no) FROM qa_reports latest WHERE latest.manifest_id=m.id AND latest.kind='PRE_RENDER')) AND NOT EXISTS(SELECT 1 FROM render_manifests snapshot,json_each(snapshot.manifest_json,'$.assets') a LEFT JOIN assets actual ON actual.id=json_extract(a.value,'$.id') AND actual.project_id=snapshot.project_id WHERE snapshot.id=m.id AND (actual.id IS NULL OR actual.availability='MISSING')) GROUP BY m.id;
